mapper.select:
SELECT GROUP_CONCAT(c.grid_name) AS grid_name, a.keeper_id_card_number AS keeper_id_card_number, a.keeper_phone_number AS keeper_phone_number, a.keeper_name,a.login_name,a.keeper_gender,a.keeper_email, DATE_FORMAT(a.keeper_birth_date,'%Y-%m-%d') keeper_birth_date,DATE_FORMAT(a.entry_time,'%Y-%m-%d') entry_time, a.wechat_number,cc.DICT_LABEL AS party, a.location_flag,a.keeper_type,a.operating_duty,a.keeper_id FROM bm_gridkeeper a LEFT JOIN bm_grid_keeper_ref b ON b.keeper_id = a.keeper_id LEFT JOIN bm_grid c ON b.grid_id = c.grid_id LEFT JOIN sys_dict_data cc ON (cc.DICT_TYPE = 'political_status' AND a.party = cc.DICT_VALUE) WHERE a.delete_flag = 0 AND b.delete_flag = 0 AND c.delete_flag = 0
and a.keeper_id in (select r.keeper_id from bm_grid_keeper_ref r where r.delete_flag = '0' and r.grid_id = #{deptId,jdbcType=VARCHAR} )
and a.province_id = #{provinceId,jdbcType=VARCHAR}
and a.city_id = #{cityId,jdbcType=VARCHAR}
and a.status = #{status}
and a.keeper_code like concat('%',#{keeperCode},'%')
and a.keeper_name like concat('%',#{keeperName},'%')
and a.login_name like concat('%',#{loginName},'%')
and a.keeper_phone_number like concat('%',#{keeperPhoneNumber},'%')
and EXISTS(SELECT t.keeper_id FROM bm_grid_keeper_ref t WHERE t.delete_flag = '0' and t.grid_id = #{gridId} AND t.keeper_id = a.keeper_id)
and (a.keeper_code like concat('%',#{keyword},'%') or a.keeper_name like concat('%',#{keyword},'%'))
and a.location_flag = #{locationFlag}
and a.keeper_type = #{keeperType}
${dataScope} GROUP BY a.keeper_id order by a.create_time DESC,a.keeper_id DESC

SELECT a.keeper_id,a.keeper_name,b.grid_id, CONCAT( SUBSTRING( a.keeper_phone_number, 1, 3 ), '****', SUBSTRING( a.keeper_phone_number, 8 )) AS keeper_phone_number, a.keeper_phone_number AS phonePlainText, sys.AVATAR as keeperPhotoUrl, (case when TIMESTAMPDIFF(MINUTE,a.take_point_time,now())<5 then '1' else '0' end) as isLine FROM bm_gridkeeper a, bm_grid_keeper_ref b, sys_user sys WHERE a.keeper_id = b.keeper_id and a.staff_id = sys.USER_ID and b.grid_id in
#{item}
and a.tenant_id = #{tenantId,jdbcType=VARCHAR} and a.industry_code = #{industryCode,jdbcType=VARCHAR} AND a.delete_flag = 0 AND b.delete_flag = 0 AND a.keeper_type = '1'
and a.keeper_id != #{keeperId,jdbcType=BIGINT}

SELECT r.keeper_id, bg.grid_name FROM bm_grid_keeper_ref r INNER JOIN bm_grid g ON r.grid_id = g.grid_id LEFT JOIN bm_grid bg ON bg.grid_id = g.parent_code WHERE r.keeper_id IN
#{keeperId}
AND r.delete_flag = 0 AND g.delete_flag = 0 AND bg.grid_name IS NOT NULL
